import * as THREE from 'three';
import type { App, Feature, FrameContext } from '../app';
import { copyPosition, copyQuaternion } from '../input';
import { RAPIER } from '../physics';

/** 検出された平面 / メッシュ 1 つぶんの表示と当たり判定 */
interface Built {
  root: THREE.Group;
  debug: THREE.Group;
  colliderDesc: RAPIER.ColliderDesc | null;
  label: string;
  offset: THREE.Vector3;
}

interface Surface {
  root: THREE.Group;
  /** 輪郭・ラベルなど、「部屋の形」の表示を切ると消える部分 */
  debug: THREE.Group;
  collider: RAPIER.Collider | null;
  /** コライダーの中心の、平面ローカル座標でのずれ */
  colliderOffset: THREE.Vector3;
  lastChangedTime: number;
  label: string;
}

/** Quest が返す semanticLabel の日本語名 */
const LABEL_NAMES: Record<string, string> = {
  floor: '床',
  ceiling: '天井',
  wall: '壁',
  'wall face': '壁',
  table: '机',
  desk: '机',
  couch: 'ソファ',
  bed: 'ベッド',
  door: 'ドア',
  'door frame': 'ドア',
  window: '窓',
  'window frame': '窓',
  screen: '画面',
  storage: '収納',
  shelf: '棚',
  lamp: '照明',
  plant: '植物',
  'wall art': '壁の絵',
  'global mesh': '部屋全体のメッシュ',
  other: 'その他',
};

const LABEL_COLORS: Record<string, number> = {
  床: 0x4f8cff,
  壁: 0x6fe09a,
  天井: 0x9aa4b8,
  机: 0xffb86b,
};
const DEFAULT_COLOR = 0xc58cff;
const MESH_COLOR = 0x5ad1e6;

/** 平面の当たり判定の厚みの半分 (m)。薄すぎると速い球がすり抜ける。 */
const PLANE_HALF_THICKNESS = 0.02;
const SURFACE_FRICTION = 0.8;
const SURFACE_RESTITUTION = 0.5;
/** 影を受ける面を、現実の面から浮かせる距離 (m)。重ねると深度センサーの誤差で影が欠ける。 */
const SHADOW_LIFT = 0.01;
const SHADOW_OPACITY = 0.3;

const _position = new THREE.Vector3();
const _quaternion = new THREE.Quaternion();
const _offset = new THREE.Vector3();

/**
 * 平面検出 (plane-detection) とメッシュ検出 (mesh-detection) の結果を、
 * 見える形 (輪郭・ワイヤーフレーム・ラベル) と物理の当たり判定にする。
 *
 * Quest では、どちらも事前の「スペースのセットアップ」で作られた部屋のデータが返る。
 * 未設定だと何も返らないので、メニューの「部屋をスキャン」からセットアップを呼び出せる。
 */
export class Room implements Feature {
  readonly name = 'room';
  visible = true;

  private readonly planes = new Map<XRPlane, Surface>();
  private readonly meshes = new Map<XRMesh, Surface>();
  private readonly group = new THREE.Group();
  /** 部屋のデータが無いときに使う、y=0 の仮の床 */
  private fallbackFloor: RAPIER.Collider | null = null;
  /** 床が検出されていないときに影を受ける、y=0 の面 */
  private readonly fallbackShadow = makeShadowReceiver(new THREE.PlaneGeometry(12, 12).rotateX(-Math.PI / 2));
  private session: XRSession | null = null;

  constructor(private readonly app: App) {
    this.fallbackShadow.visible = false;
    this.fallbackShadow.position.y = SHADOW_LIFT;
    app.scene.add(this.group, this.fallbackShadow);
    app.menu.addToggle(
      '部屋の形',
      () => this.visible,
      (value) => (this.visible = value),
    );
    app.menu.addAction('部屋をスキャン', () => {
      // Quest のスペースセットアップを開く。1 セッションにつき 1 回しか呼べない。
      this.session?.initiateRoomCapture?.().catch((error: unknown) => {
        console.warn('[room] initiateRoomCapture に失敗しました', error);
      });
    });
  }

  get planeCount(): number {
    return this.planes.size;
  }

  get meshCount(): number {
    return this.meshes.size;
  }

  /** 床として検出された平面があるか */
  get hasFloor(): boolean {
    for (const surface of this.planes.values()) if (surface.label === '床') return true;
    return false;
  }

  start(session: XRSession): void {
    this.session = session;
    this.fallbackFloor = this.app.physics.world.createCollider(
      RAPIER.ColliderDesc.cuboid(30, 0.1, 30)
        .setTranslation(0, -0.1, 0)
        .setFriction(SURFACE_FRICTION)
        .setRestitution(SURFACE_RESTITUTION),
    );
  }

  end(): void {
    for (const surface of this.planes.values()) this.dispose(surface);
    for (const surface of this.meshes.values()) this.dispose(surface);
    this.planes.clear();
    this.meshes.clear();
    if (this.fallbackFloor) this.app.physics.world.removeCollider(this.fallbackFloor, false);
    this.fallbackFloor = null;
    this.fallbackShadow.visible = false;
    this.session = null;
  }

  update(ctx: FrameContext): void {
    // detectedPlanes / detectedMeshes は「いま見えている集合」。
    // 消えたものは集合から外れ、形が変わったものは lastChangedTime が進む。
    this.sync(ctx, ctx.frame.detectedPlanes, this.planes, (plane) => plane.planeSpace, buildPlane);
    this.sync(ctx, ctx.frame.detectedMeshes, this.meshes, (mesh) => mesh.meshSpace, buildMesh);
    this.fallbackFloor?.setEnabled(this.planes.size === 0 && this.meshes.size === 0);
    this.fallbackShadow.visible = !this.hasFloor;
  }

  private sync<T extends { lastChangedTime: number }>(
    ctx: FrameContext,
    detected: ReadonlySet<T> | undefined,
    surfaces: Map<T, Surface>,
    getSpace: (item: T) => XRSpace,
    build: (item: T) => Built,
  ): void {
    if (!detected) return;
    for (const [item, surface] of surfaces) {
      if (detected.has(item)) continue;
      this.dispose(surface);
      surfaces.delete(item);
    }
    detected.forEach((item) => {
      let surface = surfaces.get(item);
      if (!surface || surface.lastChangedTime !== item.lastChangedTime) {
        if (surface) this.dispose(surface);
        const built = build(item);
        surface = {
          root: built.root,
          debug: built.debug,
          collider: built.colliderDesc ? this.app.physics.world.createCollider(built.colliderDesc) : null,
          colliderOffset: built.offset,
          lastChangedTime: item.lastChangedTime,
          label: built.label,
        };
        this.group.add(surface.root);
        surfaces.set(item, surface);
      }
      surface.debug.visible = this.visible;
      // 形はそれぞれの空間 (planeSpace / meshSpace) のローカル座標で与えられる。
      // 空間の姿勢は毎フレーム変わりうるので、そのつど取り直す。
      const pose = ctx.frame.getPose(getSpace(item), ctx.refSpace);
      if (!pose) return;
      copyPosition(_position, pose.transform.position);
      copyQuaternion(_quaternion, pose.transform.orientation);
      if (surface.root.position.equals(_position) && surface.root.quaternion.equals(_quaternion)) return;
      surface.root.position.copy(_position);
      surface.root.quaternion.copy(_quaternion);
      if (surface.collider) {
        _offset.copy(surface.colliderOffset).applyQuaternion(_quaternion).add(_position);
        surface.collider.setTranslation(_offset);
        surface.collider.setRotation(_quaternion);
      }
    });
  }

  private dispose(surface: Surface): void {
    this.group.remove(surface.root);
    surface.root.traverse((object) => {
      const mesh = object as Partial<THREE.Mesh<THREE.BufferGeometry, THREE.Material>> & Partial<THREE.Sprite>;
      mesh.geometry?.dispose();
      const material = mesh.material as (THREE.Material & { map?: THREE.Texture | null }) | undefined;
      material?.map?.dispose();
      material?.dispose();
    });
    if (surface.collider) this.app.physics.world.removeCollider(surface.collider, false);
  }
}

function describe(semanticLabel: string | undefined, fallback: string): { name: string; text: string } {
  if (!semanticLabel) return { name: fallback, text: fallback };
  const name = LABEL_NAMES[semanticLabel];
  return name ? { name, text: `${name} (${semanticLabel})` } : { name: semanticLabel, text: semanticLabel };
}

function buildPlane(plane: XRPlane): Built {
  // polygon は平面ローカルの XZ 平面上の輪郭 (y は 0)。法線は +Y。
  const points = plane.polygon.map((p) => new THREE.Vector2(p.x, p.z));
  if (points.length > 1 && points[0].equals(points[points.length - 1])) points.pop();

  const { name, text } = describe(plane.semanticLabel, plane.orientation === 'vertical' ? '垂直面' : '水平面');
  const color = LABEL_COLORS[name] ?? DEFAULT_COLOR;
  const root = new THREE.Group();
  const debug = new THREE.Group();
  root.add(debug);
  const min = new THREE.Vector2(Infinity, Infinity);
  const max = new THREE.Vector2(-Infinity, -Infinity);
  const positions = new Float32Array(points.length * 3);
  points.forEach((p, i) => {
    positions[i * 3] = p.x;
    positions[i * 3 + 2] = p.y;
    min.min(p);
    max.max(p);
  });
  if (points.length < 3) return { root, debug, colliderDesc: null, label: name, offset: new THREE.Vector3() };

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setIndex(THREE.ShapeUtils.triangulateShape(points, []).flat());
  debug.add(
    new THREE.Mesh(
      geometry,
      new THREE.MeshBasicMaterial({
        color,
        transparent: true,
        opacity: 0.16,
        side: THREE.DoubleSide,
        depthWrite: false,
      }),
    ),
    new THREE.LineLoop(geometry, new THREE.LineBasicMaterial({ color })),
  );

  const center = new THREE.Vector3((min.x + max.x) / 2, 0, (min.y + max.y) / 2);
  const label = makeLabel(text, color);
  label.position.copy(center).setY(0.04);
  debug.add(label);

  // 現実の面に仮想物体の影を落とすための、影だけが見える面。
  const receiver = makeShadowReceiver(geometry);
  receiver.position.y = SHADOW_LIFT;
  root.add(receiver);

  // 当たり判定は輪郭を囲む薄い箱にする。Quest の平面はほぼ長方形なので、これで足りる。
  const colliderDesc = RAPIER.ColliderDesc.cuboid(
    Math.max((max.x - min.x) / 2, 0.01),
    PLANE_HALF_THICKNESS,
    Math.max((max.y - min.y) / 2, 0.01),
  )
    .setFriction(SURFACE_FRICTION)
    .setRestitution(SURFACE_RESTITUTION);
  return { root, debug, colliderDesc, label: name, offset: center };
}

function buildMesh(mesh: XRMesh): Built {
  const { name } = describe(mesh.semanticLabel, 'メッシュ');
  const root = new THREE.Group();
  const debug = new THREE.Group();
  root.add(debug);
  const offset = new THREE.Vector3();
  if (mesh.indices.length < 3) return { root, debug, colliderDesc: null, label: name, offset };

  // vertices / indices はそのまま三角形メッシュ。コピーして持つ (元の配列は次の更新で変わりうる)。
  const vertices = new Float32Array(mesh.vertices);
  const indices = new Uint32Array(mesh.indices);
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
  geometry.setIndex(new THREE.BufferAttribute(indices, 1));
  debug.add(
    new THREE.Mesh(
      geometry,
      new THREE.MeshBasicMaterial({ color: MESH_COLOR, wireframe: true, transparent: true, opacity: 0.3 }),
    ),
  );
  const colliderDesc = RAPIER.ColliderDesc.trimesh(vertices, indices)
    .setFriction(SURFACE_FRICTION)
    .setRestitution(SURFACE_RESTITUTION);
  return { root, debug, colliderDesc, label: name, offset };
}

/** ShadowMaterial は影の部分だけを半透明の黒で描く。パススルー映像の上に影だけが乗る。 */
function makeShadowReceiver(geometry: THREE.BufferGeometry): THREE.Mesh {
  const receiver = new THREE.Mesh(
    geometry,
    new THREE.ShadowMaterial({ opacity: SHADOW_OPACITY, side: THREE.DoubleSide, depthWrite: false }),
  );
  receiver.receiveShadow = true;
  return receiver;
}

function makeLabel(text: string, color: number): THREE.Sprite {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 96;
  const g = canvas.getContext('2d')!;
  g.fillStyle = 'rgba(16, 20, 28, 0.8)';
  g.beginPath();
  g.roundRect(0, 0, canvas.width, canvas.height, 24);
  g.fill();
  g.fillStyle = `#${color.toString(16).padStart(6, '0')}`;
  g.font = 'bold 44px system-ui, sans-serif';
  g.textAlign = 'center';
  g.textBaseline = 'middle';
  g.fillText(text, canvas.width / 2, canvas.height / 2 + 2, canvas.width - 32);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  const sprite = new THREE.Sprite(
    new THREE.SpriteMaterial({ map: texture, depthTest: false, transparent: true }),
  );
  sprite.scale.set(0.32, 0.06, 1);
  sprite.renderOrder = 10;
  return sprite;
}
import RAPIER from '@dimforge/rapier3d-compat';
import type { Feature, FrameContext } from './app';

export { RAPIER };

/** 衝突が始まったときの通知。引数は衝突した 2 つのコライダーのハンドル。 */
export type CollisionListener = (collider1: number, collider2: number) => void;

/** 物理ワールド (Rapier)。座標系は local-floor 参照空間と同じで、単位はメートル。 */
export class Physics implements Feature {
  readonly name = 'physics';
  world!: RAPIER.World;

  private eventQueue!: RAPIER.EventQueue;
  private readonly collisionListeners: CollisionListener[] = [];

  /** WASM の読み込みが要るので、使う前に一度 await する。 */
  async init(): Promise<void> {
    await RAPIER.init();
    this.world = new RAPIER.World({ x: 0, y: -9.81, z: 0 });
    this.eventQueue = new RAPIER.EventQueue(true);
  }

  onCollisionStart(listener: CollisionListener): void {
    this.collisionListeners.push(listener);
  }

  update(ctx: FrameContext): void {
    this.world.timestep = ctx.dt;
    this.world.step(this.eventQueue);
    this.eventQueue.drainCollisionEvents((collider1, collider2, started) => {
      if (!started) return;
      for (const listener of this.collisionListeners) listener(collider1, collider2);
    });
  }
}

/** セッション開始時に要求する WebXR の機能と、このデモでの用途。 */
export interface XRFeatureInfo {
  id: string;
  label: string;
  use: string;
}

export const REQUIRED_FEATURES: XRFeatureInfo[] = [
  { id: 'local-floor', label: '床基準の座標系', use: '床を y=0 とした座標で物を置く' },
];

export const OPTIONAL_FEATURES: XRFeatureInfo[] = [
  { id: 'hand-tracking', label: 'ハンドトラッキング', use: '手でつかむ・描く・ボタンを押す' },
  { id: 'plane-detection', label: '平面検出', use: '床・壁・机の可視化と、物理の当たり判定' },
  { id: 'mesh-detection', label: 'メッシュ検出', use: '部屋の形状の可視化と、物理の当たり判定' },
  { id: 'hit-test', label: 'ヒットテスト', use: 'レイで指した現実の面に物を置く' },
  { id: 'anchors', label: 'アンカー', use: '置いた物を現実の位置に固定し、次回も復元する' },
  { id: 'depth-sensing', label: '深度センシング', use: '現実の物や手で仮想物体を隠す' },
  { id: 'light-estimation', label: '光源推定', use: '部屋の明るさに照明を合わせる' },
];

export const ALL_FEATURES = [...REQUIRED_FEATURES, ...OPTIONAL_FEATURES];
import * as THREE from 'three';
import type { App, Feature } from '../app';

/**
 * 現実の面を、実際より奥にあるものとして扱う量。距離 d (m) の面を d * (1 + RELATIVE) + ABSOLUTE に置く。
 * 深度センサーの値は毎フレーム揺れ、遠いほど誤差が大きい。そのままだと、床や壁に接している
 * 仮想物体が現実の面と前後を取り合ってチラつくので、この分だけ仮想物体を優先する。
 * 大きくするほどチラつきは減るが、現実の物のすぐ後ろにある仮想物体が隠れなくなる。
 */
const ABSOLUTE_BIAS = 0.02;
const RELATIVE_BIAS = 0.03;
/** 「くっきり」方式で周囲の深度も見るときの、中心からの距離 (画面のピクセル数) */
const TAP_RADIUS = 4;
/**
 * 「ぼかし」方式で深度を調べる範囲の半径 (画面のピクセル数)。
 * 広いほど深度の揺れが平均されてチラつきが減るが、輪郭のぼけも広がる。
 */
const SOFT_RADIUS = 12;
/**
 * 「ぼかし」方式で、仮想物体が現実の面のどれだけ奥にあれば完全に隠れるか。
 * 距離 d (m) で SOFT_FADE_ABSOLUTE + d * SOFT_FADE_RELATIVE (m)。この間は徐々に薄くなる。
 */
const SOFT_FADE_ABSOLUTE = 0.04;
const SOFT_FADE_RELATIVE = 0.04;

/** マテリアルごとの遮蔽の扱い。material.userData.occlusion で指定する。 */
export type OcclusionMode =
  /** 現実の物に隠れる (既定) */
  | 'soft'
  /** 隠れない。ポータルの中の世界など、現実の面より奥に描きたいもの。 */
  | 'ignore'
  /** 隠れる所を描かない。半透明にできない、ステンシルへの書き込み用。 */
  | 'mask';

const VERTEX_SHADER = /* glsl */ `
void main() {
  gl_Position = vec4(position, 1.0);
}`;

const FRAGMENT_SHADER = /* glsl */ `
uniform sampler2DArray depthColor;
uniform float depthWidth;
uniform float depthHeight;
// 射影行列の z の係数。深度バッファの値と、カメラからの距離 (m) を相互に変換するのに使う。
uniform float projectionA;
uniform float projectionB;

float sampleDepth(vec2 pixel) {
  vec2 coord = pixel / vec2(depthWidth, depthHeight);
  // 左右の目の映像は横に並んでいて、深度テクスチャは目ごとに層が分かれている。
  float layer = step(1.0, coord.x);
  return texture(depthColor, vec3(coord.x - layer, coord.y, layer)).r;
}

void main() {
  vec2 pixel = gl_FragCoord.xy;
  // 周囲も調べて、いちばん奥の値を使う。現実の物の輪郭では深度が手前と奥を行き来するので、
  // 奥側に寄せておくと、輪郭のチラつきが「仮想物体が少しはみ出て見える」程度で済む。
  float depth = sampleDepth(pixel);
  depth = max(depth, sampleDepth(pixel + vec2(TAP_RADIUS, TAP_RADIUS)));
  depth = max(depth, sampleDepth(pixel + vec2(-TAP_RADIUS, TAP_RADIUS)));
  depth = max(depth, sampleDepth(pixel + vec2(TAP_RADIUS, -TAP_RADIUS)));
  depth = max(depth, sampleDepth(pixel + vec2(-TAP_RADIUS, -TAP_RADIUS)));

  // 深度バッファの値 → 距離 (m) → 奥へずらす → 深度バッファの値
  float meters = projectionB / min(depth * 2.0 - 1.0 + projectionA, -1e-6);
  meters = meters * (1.0 + RELATIVE_BIAS) + ABSOLUTE_BIAS;
  gl_FragDepth = clamp((projectionB / meters - projectionA) * 0.5 + 0.5, 0.0, 1.0);
}`;

/** 「ぼかし」方式で、各マテリアルのフラグメントシェーダーの先頭に足す宣言 */
const SOFT_DECLARATIONS = /* glsl */ `
uniform sampler2DArray xrDepthTexture;
uniform vec2 xrDepthSize;
uniform vec2 xrProjection;
uniform float xrOcclusionStrength;

float xrMeters(float depth) {
  return xrProjection.y / min(depth * 2.0 - 1.0 + xrProjection.x, -1e-6);
}

// この画素の位置で、仮想物体が現実の面より手前にあれば 1、十分に奥なら 0。
float xrTap(vec2 pixel, float fragmentMeters, float fade) {
  vec2 coord = pixel / xrDepthSize;
  float layer = step(1.0, coord.x);
  float depth = texture(xrDepthTexture, vec3(coord.x - layer, coord.y, layer)).r;
  float realMeters = xrMeters(depth) * (1.0 + ${RELATIVE_BIAS.toFixed(4)}) + ${ABSOLUTE_BIAS.toFixed(4)};
  return clamp((realMeters - fragmentMeters) / fade + 1.0, 0.0, 1.0);
}

// 周囲の複数の点で前後を判定し、その平均を「見えている割合」とする。
// 深度そのものを平均すると、輪郭で手前と奥の中間という存在しない距離ができてしまうので、
// 判定の結果のほうを平均する。
float xrOcclusionVisibility() {
  if (xrOcclusionStrength < 0.5) return 1.0;
  float fragmentMeters = xrMeters(gl_FragCoord.z);
  float fade = ${SOFT_FADE_ABSOLUTE.toFixed(4)} + ${SOFT_FADE_RELATIVE.toFixed(4)} * fragmentMeters;
  vec2 pixel = gl_FragCoord.xy;
  const float r = ${SOFT_RADIUS.toFixed(1)};
  const float d = r * 0.7071;
  float sum = xrTap(pixel, fragmentMeters, fade) * 2.0;
  sum += xrTap(pixel + vec2(r, 0.0), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(-r, 0.0), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(0.0, r), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(0.0, -r), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(d, d), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(-d, d), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(d, -d), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(-d, -d), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(r * 0.5, 0.0), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(-r * 0.5, 0.0), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(0.0, r * 0.5), fragmentMeters, fade);
  sum += xrTap(pixel + vec2(0.0, -r * 0.5), fragmentMeters, fade);
  return sum / 14.0;
}
`;

/** main() の最後に足す処理 */
const SOFT_APPLY: Record<Exclude<OcclusionMode, 'ignore'>, string> = {
  // パススルー映像との合成は、フレームバッファのアルファ (乗算済み) で行われる。
  // 不透明なマテリアルはブレンドしないので、色とアルファの両方を下げて現実を透かす。
  // 半透明なマテリアルは、アルファを下げればブレンドの結果として薄くなる。
  soft: /* glsl */ `
  float xrVisible = xrOcclusionVisibility();
  if (xrVisible < 0.004) discard;
  #ifdef OPAQUE
    gl_FragColor *= xrVisible;
  #else
    gl_FragColor.a *= xrVisible;
  #endif
`,
  mask: /* glsl */ `
  if (xrOcclusionVisibility() < 0.5) discard;
`,
};

/** 全マテリアルで共有する uniform。値を書き換えると、すべてのマテリアルに反映される。 */
const softUniforms = {
  xrDepthTexture: { value: null as THREE.Texture | null },
  xrDepthSize: { value: new THREE.Vector2(1, 1) },
  xrProjection: { value: new THREE.Vector2(-1, -0.1) },
  xrOcclusionStrength: { value: 0 },
};

function occlusionMode(material: THREE.Material): OcclusionMode {
  const flags = material as THREE.Material & {
    isShaderMaterial?: boolean;
    isMeshDepthMaterial?: boolean;
    isMeshDistanceMaterial?: boolean;
  };
  // 自前のシェーダーと、影の計算用のマテリアルには手を入れない。
  if (flags.isShaderMaterial || flags.isMeshDepthMaterial || flags.isMeshDistanceMaterial) return 'ignore';
  // 深度テストをしないもの (メニュー、照準、ラベル) は、常に見せたいものなので隠さない。
  if (!material.depthTest) return 'ignore';
  return (material.userData.occlusion as OcclusionMode | undefined) ?? 'soft';
}

/**
 * 遮蔽なしで描く。XR の画面以外 (写真用のレンダーターゲットなど) へ描くときに使う。
 * 「ぼかし」方式は XR の画面の画素位置から深度を引くので、別の視点の描画には使えない。
 */
export function withoutOcclusion(render: () => void): void {
  const strength = softUniforms.xrOcclusionStrength.value;
  softUniforms.xrOcclusionStrength.value = 0;
  try {
    render();
  } finally {
    softUniforms.xrOcclusionStrength.value = strength;
  }
}

let installed = false;

/**
 * 「ぼかし」方式の遮蔽を、three.js の標準マテリアルすべてに組み込む。
 *
 * 画素ごとに薄くするには、各マテリアルのフラグメントシェーダーで現実の深度と比べる必要がある。
 * マテリアルを作る場所ごとに設定して回る代わりに、Material の既定のフック (onBeforeCompile) を
 * 差し替えて、シェーダーのコンパイル時に一括で処理を足している。
 */
function installSoftOcclusion(): void {
  if (installed) return;
  installed = true;
  // 同じ種類のマテリアルでも、遮蔽の扱いが違えば別のシェーダーになるようにする。
  THREE.Material.prototype.customProgramCacheKey = function (this: THREE.Material): string {
    return `xr-occlusion:${occlusionMode(this)}`;
  };
  THREE.Material.prototype.onBeforeCompile = function (this: THREE.Material, shader): void {
    const mode = occlusionMode(this);
    if (mode === 'ignore') return;
    const end = shader.fragmentShader.lastIndexOf('}');
    if (end < 0) return;
    Object.assign(shader.uniforms, softUniforms);
    shader.fragmentShader =
      SOFT_DECLARATIONS + shader.fragmentShader.slice(0, end) + SOFT_APPLY[mode] + shader.fragmentShader.slice(end);
  };
}

/**
 * 現実の物や自分の手で、仮想物体を隠す (depth-sensing)。方式が 2 つある。
 *
 * くっきり: 現実の深度を、仮想物体より先に深度バッファへ書いておく。three.js 標準の仕組みで、
 *   WebXRManager が毎フレーム深度テクスチャを受け取り、それを書くだけのメッシュを最初に描く。
 *   以降の仮想物体は、現実の面より奥にある画素が深度テストで落ちる。
 *   ここではそのメッシュのシェーダーを、センサーの誤差のぶん奥へずらして書くものに差し替えている。
 *   画素ごとに「見える / 見えない」の二択なので、深度が揺れる所ではチラつく。
 *
 * ぼかし: 深度バッファには書かず、各マテリアルのシェーダーの中で現実の深度と比べ、
 *   周囲の判定の平均に応じて薄くする。輪郭がなめらかになり、深度の揺れは濃淡の揺れに和らぐ。
 *   そのぶん、仮想物体を描く画素ごとに深度を何度も読むので重い。
 */
export class Occlusion implements Feature {
  readonly name = 'occlusion';
  enabled = true;
  /** true なら「ぼかし」、false なら「くっきり」 */
  soft = true;
  /** 深度データが届いているか */
  active = false;

  private patched: THREE.Mesh | null = null;
  private material: THREE.ShaderMaterial | null = null;

  constructor(private readonly app: App) {
    installSoftOcclusion();
    app.menu.addToggle(
      '遮蔽',
      () => this.enabled,
      (value) => (this.enabled = value),
    );
    app.menu.addToggle(
      '遮蔽をぼかす',
      () => this.soft,
      (value) => (this.soft = value),
    );
  }

  update(): void {
    const xr = this.app.renderer.xr;
    // 深度データが一度も届いていない間は null。
    const mesh = xr.getDepthSensingMesh();
    const texture = xr.getDepthTexture();
    this.active = mesh !== null && texture !== null;
    softUniforms.xrDepthTexture.value = texture;
    softUniforms.xrOcclusionStrength.value = this.active && this.enabled && this.soft ? 1 : 0;
    if (!mesh) return;
    mesh.visible = this.enabled && !this.soft;
    if (mesh !== this.patched) this.patch(mesh);

    // 深度テクスチャは描画と同じ near / far で作られている (three.js がカメラ側を合わせる)。
    // 両目で共通なので、片目の射影行列から係数を取ればよい。
    const eye = xr.getCamera().cameras[0];
    if (!eye || !this.material) return;
    const a = eye.projectionMatrix.elements[10];
    const b = eye.projectionMatrix.elements[14];
    this.material.uniforms.projectionA.value = a;
    this.material.uniforms.projectionB.value = b;
    softUniforms.xrProjection.value.set(a, b);
    softUniforms.xrDepthSize.value.set(eye.viewport.z, eye.viewport.w);
  }

  end(): void {
    this.active = false;
    this.patched = null;
    this.material?.dispose();
    this.material = null;
    softUniforms.xrDepthTexture.value = null;
    softUniforms.xrOcclusionStrength.value = 0;
  }

  /** three.js が作ったメッシュのマテリアルを差し替える。テクスチャなどの値は元のものを引き継ぐ。 */
  private patch(mesh: THREE.Mesh): void {
    const original = mesh.material as THREE.ShaderMaterial;
    this.material?.dispose();
    this.material = new THREE.ShaderMaterial({
      vertexShader: VERTEX_SHADER,
      fragmentShader: FRAGMENT_SHADER,
      defines: {
        ABSOLUTE_BIAS: ABSOLUTE_BIAS.toFixed(4),
        RELATIVE_BIAS: RELATIVE_BIAS.toFixed(4),
        TAP_RADIUS: TAP_RADIUS.toFixed(1),
      },
      uniforms: {
        depthColor: original.uniforms.depthColor,
        depthWidth: original.uniforms.depthWidth,
        depthHeight: original.uniforms.depthHeight,
        projectionA: { value: -1 },
        projectionB: { value: -0.1 },
      },
    });
    mesh.material = this.material;
    original.dispose();
    this.patched = mesh;
  }
}
