280	   * 現実の物が押しのけられるよう、重なった物は起こす。
281	   */
282	  private wakeTouching(): void {
283	    const world = this.app.physics.world;
284	    for (let i = 0; i < this.count; i++) {
285	      const collider = this.colliders[i];
286	      world.intersectionsWithShape(
287	        collider.translation(),
288	        IDENTITY,
